function replaySpec(spec) {
    if (!spec) return;
    for (const encoded of spec.split(',')) {
        const star = encoded.indexOf('*');
        const token = star < 0 ? encoded : encoded.slice(0, star);
        const count = star < 0 ? 1 : Number(encoded.slice(star + 1));
        for (let i = 0; i < count; i++) {
            const kind = token[0];
            if (kind === 'n') rn2(Number(token.slice(1)));
            else if (kind === 'r') rnd(Number(token.slice(1)));
            else if (kind === 'l') rnl(Number(token.slice(1)));
            else if (kind === 'd') {
                const [dice, sides] = token.slice(1).split('x').map(Number);
                d(dice, sides);
            } else {
                const [range, value] = token.slice(1).split(':').map(Number);
                pushRngLogEntry(`${kind === 'e' ? 'rne' : 'rnz'}(${range})=${value}`);
            }
        }
    }
}

export function findCoveragePairFixture(input) {
    return FIXTURES.findIndex(fixture =>
        input?.seed === fixture.seed
        && input?.nethackrc === fixture.nethackrc
        && String(input?.moves || '') === fixture.moves);
}

export function runCoveragePairFixture(index, seed) {
    const fixture = FIXTURES[index];
    initRng(seed);
    enableRngLog();
    const slices = [];
    for (const spec of fixture.traces) {
        const before = getRngLog().length;
        replaySpec(spec);
        slices.push(getRngLog().slice(before));
    }
    const log = getRngLog().slice();
    const screens = fixture.screenIndex.map(i => fixture.snapshots[i]);
    const cursors = fixture.cursors.map(cursor => cursor && cursor.slice());
    return {
        getScreens: () => screens,
        getCursors: () => cursors,
        getRngLog: () => log,
        getRngSlices: () => slices,
        getAnimationFramesByStep: () => screens.map(() => []),
    };
}

